const stats = $('Get stats').first().json;
const cutoff = Date.now() - 24 * 60 * 60 * 1000;
const recent = $('Get logs')
  .all()
  .map((item) => item.json)
  .filter((entry) => entry.question && new Date(entry.created_at).getTime() >= cutoff)
  .slice(0, 5);

const latency =
  stats.average_latency_ms == null
    ? 'n/a'
    : `${Math.round(stats.average_latency_ms)} ms`;

const landingPages = Number(
  $('Count landing pages').first().json.landing_pages ?? 0,
);

const questions = recent
  .map((entry) => {
    const question = String(entry.question).replace(/\s+/g, ' ').slice(0, 90);
    return `• ${question} (${entry.latency_ms} ms)`;
  })
  .join('\n');

const message = [
  'Cortex morning digest',
  '',
  `Documents: ${stats.documents}`,
  `Landing pages: ${landingPages}`,
  `Likes: ${stats.likes}`,
  `Dislikes: ${stats.dislikes}`,
  `Average latency: ${latency}`,
  '',
  questions || 'No questions in the last 24 hours.',
].join('\n');

return [{ json: { message } }];
